package android.os;public class Binder implements IBinder {final int uid=Process.myUid();static final ThreadLocal<Integer> CALLER=ThreadLocal.withInitial(()->10221);public static int getCallingUid(){return CALLER.get();}public static long clearCallingIdentity(){int old=CALLER.get();CALLER.set(Process.myUid());return old;}public static void restoreCallingIdentity(long v){CALLER.set((int)v);}public boolean transact(int c,Parcel i,Parcel o,int f)throws RemoteException {int old=Process.myUid(),caller=CALLER.get();CALLER.set(old);Process.UID.set(uid);try{return onTransact(c,i,o,f);}finally{Process.UID.set(old);CALLER.set(caller);}}protected boolean onTransact(int c,Parcel i,Parcel o,int f)throws RemoteException{return false;}}
